"""matplotlib.stackplot — re-export of the pyplot stackplot.

Upstream defines `matplotlib.stackplot.stackplot(...)` as the canonical
implementation that `pyplot.stackplot` defers to. The plotly shim
flips that ownership — pyplot owns the implementation — so this module
just re-exports it for callers that do `from matplotlib.stackplot
import stackplot`.
"""

from matplotlib.pyplot import stackplot  # noqa: F401

__all__ = ['stackplot']
